-- 217 (16/11/2026, lô 53): 6 bài Nói TCF cho cây Luyện thi TCF, 24 lượt ghi âm, 6 miễn phí, 0 VIP.
-- Sinh bởi scripts/nhap/lo53_noi_tcf.mjs. Bài ghiAm; AI nhận xét từng lượt bằng nhan-xet-noi (lời nhắc TCF). Chạy lại an toàn.
-- TCF-PO-1 #1 Oral TCF : se présenter à l'examinateur (miễn phí)
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('lo53tcfpo01', 'practice', 'Oral TCF : se présenter à l''examinateur', 'TCF', array['Production orale']::text[], 'practice', null, null, '<p>Tâche 1 du TCF : l''examinateur vous pose des questions sur vous, votre vie et vos projets. Il n''y a pas de préparation. Répondez à chaque question en 3 ou 4 phrases.</p><p><strong>Comme au TCF :</strong> parlez sans lire. Enregistrez une réponse pour chaque étape ; l''IA commente chaque enregistrement, puis vous pouvez écouter une réponse modèle.</p>', null, null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• un comptable, une comptable : kế toán\n• bruyant (adjectif) : ồn ào\n• la circulation : giao thông\n• immigrer (verbe) : nhập cư\n• faire reconnaître son diplôme : công nhận bằng cấp","explications":"• Đừng trả lời một từ: mỗi câu nói 3 đến 4 câu, có một chi tiết cụ thể (tên, nơi, ví dụ).\n• Câu hỏi về dự định thì dùng futur simple hoặc « je voudrais », « j''aimerais ».","ghiAm":true,"kyNang":"TCF-PO-1","vong":"hoc","thuTu":1}'::jsonb, '2026-11-16T14:00:00.000Z') on conflict (id) do nothing returning id)
insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation)
select v.* from e, (values
  ('lo53tcfpo01q01', 'lo53tcfpo01', 1, 'open', 'Bonjour. Pouvez-vous vous présenter, s''il vous plaît ?', '{"giay":60}'::jsonb, '{"model":"Bonjour. Je m''appelle Thu, j''ai vingt-huit ans et je suis vietnamienne. J''habite à Hô Chi Minh-Ville avec mon mari et notre petite fille de trois ans. Je travaille comme comptable dans une entreprise d''import-export."}'::jsonb, null),
  ('lo53tcfpo01q02', 'lo53tcfpo01', 2, 'open', 'Où habitez-vous ? Pouvez-vous décrire votre ville ?', '{"giay":60}'::jsonb, '{"model":"J''habite à Hô Chi Minh-Ville, dans le sud du Vietnam. C''est une très grande ville, dynamique et un peu bruyante, avec beaucoup de motos. J''aime surtout ses marchés et sa cuisine de rue, mais la circulation est parfois difficile."}'::jsonb, null),
  ('lo53tcfpo01q03', 'lo53tcfpo01', 3, 'open', 'Qu''est-ce que vous faites dans la vie ?', '{"giay":60}'::jsonb, '{"model":"Je suis comptable. Je prépare les factures et je contrôle les dépenses de l''entreprise. C''est un travail précis qui demande de la patience. Ce que j''apprécie, c''est de travailler avec des clients étrangers."}'::jsonb, null),
  ('lo53tcfpo01q04', 'lo53tcfpo01', 4, 'open', 'Que faites-vous pendant votre temps libre ?', '{"giay":60}'::jsonb, '{"model":"Le week-end, je passe du temps avec ma famille : nous allons au parc ou chez mes parents. J''aime aussi cuisiner et regarder des films français, ça m''aide à progresser. Quand j''ai le temps, je fais du yoga."}'::jsonb, null),
  ('lo53tcfpo01q05', 'lo53tcfpo01', 5, 'open', 'Pourquoi apprenez-vous le français ?', '{"giay":60}'::jsonb, '{"model":"J''apprends le français parce que nous voulons immigrer au Canada, au Québec. Le TCF est obligatoire pour notre dossier. Et puis j''aime cette langue depuis le lycée, je trouve qu''elle est élégante."}'::jsonb, null),
  ('lo53tcfpo01q06', 'lo53tcfpo01', 6, 'open', 'Quels sont vos projets pour les prochaines années ?', '{"giay":60}'::jsonb, '{"model":"Si tout va bien, nous partirons à Montréal dans deux ans. Je voudrais reprendre mes études pour faire reconnaître mon diplôme, puis trouver un poste de comptable. Plus tard, j''aimerais acheter une maison avec un jardin."}'::jsonb, null)
) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);

-- TCF-PO-1 #2 Oral TCF : habitudes et souvenirs (miễn phí)
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('lo53tcfpo02', 'practice', 'Oral TCF : habitudes et souvenirs', 'TCF', array['Production orale']::text[], 'practice', null, null, '<p>Tâche 1 du TCF : l''examinateur continue l''entretien et vous pose des questions sur votre quotidien et vos souvenirs. Répondez en 3 ou 4 phrases, avec des exemples.</p><p><strong>Comme au TCF :</strong> parlez sans lire. Enregistrez une réponse pour chaque étape ; l''IA commente chaque enregistrement, puis vous pouvez écouter une réponse modèle.</p>', null, null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• être à la retraite : đã nghỉ hưu\n• un frère aîné : anh trai\n• s''entraider (verbe) : giúp đỡ nhau\n• marquer (verbe) : để lại dấu ấn\n• en revanche : ngược lại","explications":"• Kể chuyện đã qua: passé composé cho sự việc, imparfait cho bối cảnh và thói quen.\n• Câu « aimez / n''aimez pas » nên có cả hai vế, nối bằng « en revanche » hoặc « par contre ».","ghiAm":true,"kyNang":"TCF-PO-1","vong":"on","thuTu":2}'::jsonb, '2026-11-16T14:00:01.000Z') on conflict (id) do nothing returning id)
insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation)
select v.* from e, (values
  ('lo53tcfpo02q01', 'lo53tcfpo02', 1, 'open', 'Parlez-moi de votre famille.', '{"giay":60}'::jsonb, '{"model":"J''ai une petite famille. Mes parents habitent à Huê, ils sont à la retraite. J''ai un frère aîné qui est médecin et qui a deux enfants. Nous nous retrouvons tous ensemble pour le Têt, c''est le moment de l''année que je préfère."}'::jsonb, null),
  ('lo53tcfpo02q02', 'lo53tcfpo02', 2, 'open', 'Comment se passe une journée normale pour vous ?', '{"giay":60}'::jsonb, '{"model":"Je me lève vers six heures et demie, je prépare le petit-déjeuner et j''emmène mon fils à l''école. Je commence le travail à huit heures. Le soir, je rentre vers dix-huit heures, nous dînons, puis j''étudie le français une demi-heure."}'::jsonb, null),
  ('lo53tcfpo02q03', 'lo53tcfpo02', 3, 'open', 'Racontez-moi votre dernier voyage.', '{"giay":60}'::jsonb, '{"model":"L''été dernier, je suis allé à Đà Lạt avec des amis. Il faisait frais, c''était agréable après la chaleur de la ville. Nous avons visité des fermes de fraises et nous avons fait une randonnée autour du lac. J''aimerais y retourner."}'::jsonb, null),
  ('lo53tcfpo02q04', 'lo53tcfpo02', 4, 'open', 'Quel est votre plat préféré ? Pourquoi ?', '{"giay":60}'::jsonb, '{"model":"Mon plat préféré, c''est le phở de ma mère. C''est une soupe de nouilles au bœuf, avec beaucoup d''herbes. Je l''aime parce qu''elle me rappelle mon enfance, les dimanches matin à la maison. J''ai essayé de la préparer, mais ce n''est jamais aussi bon !"}'::jsonb, null),
  ('lo53tcfpo02q05', 'lo53tcfpo02', 5, 'open', 'Quel souvenir d''enfance vous a marqué ?', '{"giay":60}'::jsonb, '{"model":"Quand j''avais huit ans, mon grand-père m''a appris à faire du vélo. Je tombais tout le temps, mais il restait patient. Le jour où j''ai réussi à rouler seul, il était plus fier que moi. Il est mort depuis, mais je pense souvent à ce moment."}'::jsonb, null),
  ('lo53tcfpo02q06', 'lo53tcfpo02', 6, 'open', 'Qu''est-ce que vous aimez et qu''est-ce que vous n''aimez pas dans votre travail ou vos études ?', '{"giay":60}'::jsonb, '{"model":"Dans mon travail, j''aime l''ambiance : mes collègues sont sympathiques et on s''entraide. En revanche, je n''aime pas les longues réunions qui ne servent à rien. Parfois, je dois aussi travailler tard le soir, et c''est fatigant."}'::jsonb, null)
) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);

-- TCF-PO-2 #1 Oral TCF : s'inscrire dans une salle de sport (miễn phí)
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('lo53tcfpo03', 'practice', 'Oral TCF : s''inscrire dans une salle de sport', 'TCF', array['Production orale']::text[], 'practice', null, null, '<p>Tâche 2 du TCF. Situation : vous voulez vous inscrire dans une salle de sport près de chez vous. L''examinateur joue le rôle du réceptionniste. Posez-lui des questions pour obtenir toutes les informations utiles. C''est VOUS qui posez les questions.</p><p><strong>Comme au TCF :</strong> parlez sans lire. Enregistrez une réponse pour chaque étape ; l''IA commente chaque enregistrement, puis vous pouvez écouter une réponse modèle.</p>', null, null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• un renseignement : thông tin\n• un abonnement mensuel / annuel : vé tháng / vé năm\n• les frais d''inscription : phí đăng ký\n• une séance d''essai : buổi tập thử\n• résilier (verbe) : huỷ (hợp đồng)","explications":"• Tâche 2 chấm khả năng ĐẶT CÂU HỎI: đổi kiểu hỏi (Est-ce que…, Quel…, Combien…, Est-il possible de…) để không lặp.\n• Mở bằng lời chào và lý do, kết bằng lời cảm ơn: phần phù hợp tình huống cũng được chấm.","ghiAm":true,"kyNang":"TCF-PO-2","vong":"hoc","thuTu":1}'::jsonb, '2026-11-16T14:00:02.000Z') on conflict (id) do nothing returning id)
insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation)
select v.* from e, (values
  ('lo53tcfpo03q01', 'lo53tcfpo03', 1, 'open', 'Saluez, présentez votre demande, puis posez des questions sur les horaires d''ouverture et les activités proposées.', '{"giay":90}'::jsonb, '{"model":"Bonjour madame. Je viens d''emménager dans le quartier et je voudrais m''inscrire dans votre salle. Est-ce que je pourrais avoir quelques renseignements ? Quels sont vos horaires d''ouverture ? Est-ce que la salle est ouverte le dimanche ? Et quelles activités proposez-vous ? Il y a des cours collectifs, par exemple du yoga ou de la natation ?"}'::jsonb, null),
  ('lo53tcfpo03q02', 'lo53tcfpo03', 2, 'open', 'Posez des questions sur les prix, les formules d''abonnement et les réductions possibles.', '{"giay":90}'::jsonb, '{"model":"Combien coûte l''abonnement ? Est-ce qu''il y a une différence entre l''abonnement mensuel et l''abonnement annuel ? Les cours collectifs sont-ils compris dans le prix ? Je suis étudiant : est-ce que vous faites des réductions pour les étudiants ? Et est-ce qu''il y a des frais d''inscription ?"}'::jsonb, null),
  ('lo53tcfpo03q03', 'lo53tcfpo03', 3, 'open', 'Posez des questions sur les conditions (certificat médical, séance d''essai, résiliation), puis remerciez et prenez congé.', '{"giay":90}'::jsonb, '{"model":"Est-ce qu''il faut un certificat médical pour s''inscrire ? Est-il possible de faire une séance d''essai gratuite avant de décider ? Et si je déménage, est-ce que je peux arrêter l''abonnement facilement ? Quel est le délai ? Très bien, merci beaucoup pour toutes ces informations. Je reviendrai demain avec mes papiers. Bonne journée !"}'::jsonb, null)
) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);

-- TCF-PO-2 #2 Oral TCF : louer un appartement (miễn phí)
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('lo53tcfpo04', 'practice', 'Oral TCF : louer un appartement', 'TCF', array['Production orale']::text[], 'practice', null, null, '<p>Tâche 2 du TCF. Situation : vous cherchez un appartement à louer et vous appelez une agence immobilière pour une annonce. L''examinateur joue le rôle de l''agent immobilier. Posez-lui des questions pour savoir si l''appartement vous convient.</p><p><strong>Comme au TCF :</strong> parlez sans lire. Enregistrez une réponse pour chaque étape ; l''IA commente chaque enregistrement, puis vous pouvez écouter une réponse modèle.</p>', null, null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• un deux-pièces : căn hộ hai phòng\n• les charges (nom féminin pluriel) : phí dịch vụ\n• la caution : tiền đặt cọc\n• un garant : người bảo lãnh\n• à proximité : gần đó","explications":"• Chuẩn bị 2 phút: ghi nhanh 4 nhóm câu hỏi (nhà, tiền, giấy tờ, lịch xem) để không cạn ý giữa chừng.\n• Lắng nghe câu trả lời của giám khảo rồi hỏi tiếp từ đó (« Et le chauffage, il est compris ? »).","ghiAm":true,"kyNang":"TCF-PO-2","vong":"on","thuTu":2}'::jsonb, '2026-11-16T14:00:03.000Z') on conflict (id) do nothing returning id)
insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation)
select v.* from e, (values
  ('lo53tcfpo04q01', 'lo53tcfpo04', 1, 'open', 'Présentez-vous et posez des questions sur le logement : surface, nombre de pièces, étage, équipements, quartier.', '{"giay":90}'::jsonb, '{"model":"Bonjour monsieur, j''appelle au sujet de l''annonce pour le deux-pièces rue Victor-Hugo. Quelle est la surface de l''appartement ? Il est à quel étage ? Est-ce qu''il y a un ascenseur ? La cuisine est-elle équipée ? Et le quartier, il est calme ? Il y a des commerces et une station de métro à proximité ?"}'::jsonb, null),
  ('lo53tcfpo04q02', 'lo53tcfpo04', 2, 'open', 'Posez des questions sur le loyer, les charges, la caution et les documents à fournir.', '{"giay":90}'::jsonb, '{"model":"Quel est le montant du loyer ? Est-ce que les charges sont comprises ? Qu''est-ce qu''elles comprennent exactement, le chauffage et l''eau ? Combien faut-il verser pour la caution ? Et quels documents dois-je fournir pour le dossier ? Est-ce qu''un garant est obligatoire ?"}'::jsonb, null),
  ('lo53tcfpo04q03', 'lo53tcfpo04', 3, 'open', 'Posez des questions sur la visite et la date d''entrée, puis concluez poliment.', '{"giay":90}'::jsonb, '{"model":"L''appartement est disponible à partir de quand ? Est-ce que je pourrais le visiter cette semaine ? Le jeudi après dix-huit heures, est-ce que ça vous conviendrait ? Parfait. À quelle adresse dois-je vous retrouver ? Merci beaucoup, monsieur, à jeudi alors. Au revoir."}'::jsonb, null)
) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);

-- TCF-PO-3 #1 Oral TCF : le télétravail pour tous ? (miễn phí)
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('lo53tcfpo05', 'practice', 'Oral TCF : le télétravail pour tous ?', 'TCF', array['Production orale']::text[], 'practice', null, null, '<p>Tâche 3 du TCF. Sujet : « Le télétravail devrait-il devenir la norme ? » Donnez votre opinion de manière claire et argumentée. Il n''y a pas de préparation.</p><p><strong>Comme au TCF :</strong> parlez sans lire. Enregistrez une réponse pour chaque étape ; l''IA commente chaque enregistrement, puis vous pouvez écouter une réponse modèle.</p>', null, null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• la norme : chuẩn mực, điều mặc định\n• sans cesse : liên tục\n• être interrompu : bị ngắt quãng\n• une objection : ý phản bác\n• un modèle mixte : mô hình kết hợp","explications":"• Nói lập trường NGAY câu thứ hai: giám khảo cần biết bạn nghĩ gì trước khi nghe lý lẽ.\n• Gặp phản bác thì đồng ý một phần (« C''est vrai, mais… ») rồi kéo về ý mình: đó là kỹ năng được chấm ở tâche 3.","ghiAm":true,"kyNang":"TCF-PO-3","vong":"hoc","thuTu":1}'::jsonb, '2026-11-16T14:00:04.000Z') on conflict (id) do nothing returning id)
insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation)
select v.* from e, (values
  ('lo53tcfpo05q01', 'lo53tcfpo05', 1, 'open', 'Présentez le sujet, donnez clairement votre position et un premier argument.', '{"giay":90}'::jsonb, '{"model":"On parle beaucoup du télétravail depuis quelques années. Faut-il en faire la norme ? Personnellement, je pense que le télétravail est une bonne chose, mais qu''il ne doit pas remplacer complètement le bureau. Mon premier argument, c''est le temps gagné : beaucoup de salariés passent plus d''une heure par jour dans les transports, et ce temps pourrait servir à se reposer ou à voir sa famille."}'::jsonb, null),
  ('lo53tcfpo05q02', 'lo53tcfpo05', 2, 'open', 'Donnez un deuxième argument, avec un exemple concret (votre expérience ou celle d''un proche).', '{"giay":90}'::jsonb, '{"model":"Ensuite, le télétravail permet souvent d''être plus concentré. Par exemple, ma sœur travaille dans une banque. Au bureau, elle est sans cesse interrompue par des collègues ou des réunions. Depuis qu''elle travaille de chez elle deux jours par semaine, elle dit qu''elle fait en une journée ce qu''elle faisait avant en deux."}'::jsonb, null),
  ('lo53tcfpo05q03', 'lo53tcfpo05', 3, 'open', 'L''examinateur réagit : « Mais beaucoup de salariés se sentent seuls en télétravail. » Répondez à cette objection, puis concluez.', '{"giay":90}'::jsonb, '{"model":"C''est vrai, et c''est pour cela que je ne suis pas pour le télétravail à cent pour cent. L''être humain a besoin de contacts, et les échanges informels au bureau sont importants pour l''équipe. À mon avis, la meilleure solution est un modèle mixte : deux ou trois jours à la maison, le reste au bureau. En conclusion, le télétravail ne doit pas devenir la norme, mais une possibilité offerte à tous."}'::jsonb, null)
) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);

-- TCF-PO-3 #2 Oral TCF : des villes sans voitures ? (miễn phí)
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('lo53tcfpo06', 'practice', 'Oral TCF : des villes sans voitures ?', 'TCF', array['Production orale']::text[], 'practice', null, null, '<p>Tâche 3 du TCF. Sujet : « Faut-il interdire la voiture dans le centre des villes ? » Donnez votre opinion de manière claire et argumentée. Il n''y a pas de préparation.</p><p><strong>Comme au TCF :</strong> parlez sans lire. Enregistrez une réponse pour chaque étape ; l''IA commente chaque enregistrement, puis vous pouvez écouter une réponse modèle.</p>', null, null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• un centre piéton : khu phố đi bộ\n• les maladies respiratoires : bệnh hô hấp\n• un livreur : người giao hàng\n• prévoir des exceptions : dự liệu ngoại lệ\n• une navette : xe đưa đón","explications":"• Dùng từ nối để giám khảo theo kịp: d''abord, ensuite, par exemple, en conclusion.\n• Ví dụ có thật (nơi đã đến, người quen) thuyết phục hơn số liệu bạn không chắc.","ghiAm":true,"kyNang":"TCF-PO-3","vong":"on","thuTu":2}'::jsonb, '2026-11-16T14:00:05.000Z') on conflict (id) do nothing returning id)
insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation)
select v.* from e, (values
  ('lo53tcfpo06q01', 'lo53tcfpo06', 1, 'open', 'Présentez le sujet, donnez clairement votre position et un premier argument.', '{"giay":90}'::jsonb, '{"model":"Dans beaucoup de grandes villes, on se demande s''il faut interdire les voitures dans le centre. Pour ma part, je suis plutôt favorable à cette idée. D''abord, pour la santé : la pollution de l''air provoque des maladies respiratoires, surtout chez les enfants et les personnes âgées. Moins de voitures, c''est un air plus propre pour tout le monde."}'::jsonb, null),
  ('lo53tcfpo06q02', 'lo53tcfpo06', 2, 'open', 'Donnez un deuxième argument, avec un exemple concret.', '{"giay":90}'::jsonb, '{"model":"Ensuite, un centre sans voitures est plus agréable à vivre. Par exemple, l''année dernière, j''ai visité une ville européenne où le centre est piéton. Les rues étaient calmes, il y avait des terrasses, des enfants qui jouaient, des gens à vélo. Les commerces avaient beaucoup de clients, parce que les gens prenaient le temps de se promener."}'::jsonb, null),
  ('lo53tcfpo06q03', 'lo53tcfpo06', 3, 'open', 'L''examinateur réagit : « Et les personnes âgées, les livreurs, les commerçants ? » Répondez à cette objection, puis concluez.', '{"giay":90}'::jsonb, '{"model":"C''est une bonne question, il ne faut oublier personne. On peut prévoir des exceptions : les livraisons le matin, les taxis, les voitures des personnes handicapées. Il faut aussi développer les transports en commun et les navettes gratuites avant d''interdire. En conclusion, je suis pour un centre sans voitures, mais seulement si la ville propose de vraies solutions pour se déplacer."}'::jsonb, null)
) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
